package org.openidentity.samples.microsoftad;
import jakarta.servlet.http.HttpSession;import org.openidentity.ad.*;import org.openidentity.ad.ldap.*;import org.openidentity.ad.spnego.*;import org.openidentity.auth.*;import org.openidentity.core.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.nio.file.*;import java.security.SecureRandom;import java.util.*;

@SpringBootApplication @RestController
public class MicrosoftAdApplication {
 static final String VERIFIED="VERIFIED_AD",PENDING="AD_BIND_PENDING";record Pending(VerifiedAdPrincipal p,ExternalAdBindingV1.Binding b,byte[] challenge,byte[] audience,byte[] nonce,byte[] contextHash){}
 private final SpnegoAcceptor spnego;private final AdPrincipalResolver ldap;private final InMemoryExternalAdBindingRegistry registry;private final InMemoryExternalAdBindingRegistry.Policy policy;private final FileCanonicalIdentityStateRepository states;private final Oi015Verifier verifier;
 public MicrosoftAdApplication(SpnegoAcceptor s,AdPrincipalResolver l,InMemoryExternalAdBindingRegistry r,InMemoryExternalAdBindingRegistry.Policy p,FileCanonicalIdentityStateRepository st,Oi015Verifier v){spnego=s;ldap=l;registry=r;policy=p;states=st;verifier=v;}
 public static void main(String[] a){SpringApplication.run(MicrosoftAdApplication.class,a);}
 @Bean static SpnegoAcceptor spnego(){return new SpnegoAcceptor(req("OPENIDENTITY_KERBEROS_SERVICE_PRINCIPAL"),Path.of(req("OPENIDENTITY_KERBEROS_KEYTAB")));}
 @Bean static AdPrincipalResolver ldap(){return new LdapAdPrincipalResolver(new LdapAdPrincipalResolver.Profile("microsoft-ad",env("OPENIDENTITY_AD_HOST","DC01.oi-test.internal"),636,env("OPENIDENTITY_AD_BASE_DN","DC=oi-test,DC=internal"),env("OPENIDENTITY_AD_BIND_DN","oi-ldap@oi-test.internal"),req("OPENIDENTITY_LDAP_BIND_PASSWORD"),dir(),true));}
 @Bean static FileCanonicalIdentityStateRepository states(){return new FileCanonicalIdentityStateRepository(Path.of(req("OPENIDENTITY_STATE_DIR")));}
 @Bean static InMemoryExternalAdBindingRegistry registry(){return new InMemoryExternalAdBindingRegistry(Path.of(req("OPENIDENTITY_AD_BINDING_STORE")));}
 @Bean static Oi015Verifier verifier(FileCanonicalIdentityStateRepository s){return new Oi015Verifier(new CanonicalAuthenticationStateResolver(s),300);}
 @Bean static InMemoryExternalAdBindingRegistry.Policy policy(FileCanonicalIdentityStateRepository s){return new InMemoryExternalAdBindingRegistry.Policy(){public boolean directoryTrusted(byte[] d){return Arrays.equals(d,dir());}public boolean serviceAllowed(byte[] d,String x){return "openidentity-ad-link-service".equals(x);}public boolean mechanismAllowed(byte[] d,int m){return m==ExternalAdBindingV1.KERBEROS_SPNEGO;}public boolean identityActive(byte[] id){var x=s.resolve(id);return x!=null&&x.active();}public long currentAuthenticationGeneration(byte[] id){var x=s.resolve(id);if(x==null)throw new IllegalArgumentException("identity");return x.authenticationAuthority().generation();}};}
 @GetMapping("/") ResponseEntity<?> home(@RequestHeader(value="Authorization",required=false)String a,HttpSession session){
  VerifiedAdPrincipal p=authenticate(a,session);if(p==null)return challenge(null);session.setAttribute(VERIFIED,p);
  try{var r=registry.resolve(ExternalAdPrincipalBridge.registryPrincipal(p),now(),policy);return ResponseEntity.ok(Map.of("status","AUTHENTICATED","identity",hex(r.identity()),"provider","MICROSOFT_ACTIVE_DIRECTORY","principalResolution","LDAPS","authentication","KERBEROS_SPNEGO","productionAuthentication",true,"bindingStatus","ACTIVE","objectGuidLdapOctetsHex",hex(p.objectGuid())));}
  catch(ExternalAdBindingException e){if(e.error()!=ExternalAdBindingError.BINDING_NOT_FOUND)throw e;return ResponseEntity.ok(Map.of("status","MICROSOFT_AD_AUTHENTICATED","provider","MICROSOFT_ACTIVE_DIRECTORY","authentication","KERBEROS_SPNEGO","productionAuthentication",true,"principalResolution","LDAPS","objectGuidLdapOctetsHex",hex(p.objectGuid()),"next","GET /openidentity/link/begin?identity=<64-hex OpenIdentity ID>"));}
 }
 @GetMapping("/openidentity/link/begin") Map<String,String> begin(@RequestParam String identity,HttpSession s){var p=(VerifiedAdPrincipal)s.getAttribute(VERIFIED);if(p==null)throw new IllegalStateException("Microsoft AD authentication required");byte[] id=HexFormat.of().parseHex(identity);var st=states.resolve(id);if(id.length!=32||st==null)throw new IllegalArgumentException("identity");long gen=policy.currentAuthenticationGeneration(id),t=now();var b=new ExternalAdBindingV1.Binding(id,p.directoryId(),p.objectGuid(),p.serviceId(),t,null,gen);byte[] ch=random(),aud=random(),nonce=random(),ctx=ExternalAdBindingV1.encodeContext(ExternalAdBindingV1.BIND,b,p.authenticationMechanism(),ch,null),hash=ExternalAdBindingV1.contextHash(ctx);s.setAttribute(PENDING,new Pending(p,b,ch,aud,nonce,hash));return Map.of("purpose","openidentity.external-ad.bind","stateHashHex",hex(st.stateHash()),"authenticationGeneration",Long.toString(gen),"audienceHex",hex(aud),"nonceHex",hex(nonce),"contextHashHex",hex(hash));}
 @PostMapping(value="/openidentity/link/complete",consumes="text/plain") Map<String,Object> complete(@RequestBody String body,HttpSession s){var p=(Pending)s.getAttribute(PENDING);if(p==null)throw new IllegalStateException("No pending Microsoft AD binding ceremony");var secured=Oi015Codec.decode(HexFormat.of().parseHex(body.trim()));var vr=verifier.tryVerify(secured,p.audience(),"openidentity.external-ad.bind",p.nonce(),p.contextHash(),now());if(!vr.valid())throw new ExternalAdBindingException(vr.contextMismatch()?ExternalAdBindingError.BINDING_CONTEXT_MISMATCH:ExternalAdBindingError.BINDING_AUTHORIZATION_INVALID);var rp=ExternalAdPrincipalBridge.registryPrincipal(p.p());var state=registry.bind(rp,p.b().identity(),p.b().createdAt(),p.b().expiresAt(),p.challenge(),new InMemoryExternalAdBindingRegistry.Authorization(true,"openidentity.external-ad.bind",true,false),policy);s.removeAttribute(PENDING);return Map.of("status","BOUND","identity",hex(p.b().identity()),"bindingId",hex(state.bindingId()),"provider","MICROSOFT_ACTIVE_DIRECTORY","productionAuthentication",true,"next","/");}
 private VerifiedAdPrincipal authenticate(String a,HttpSession s){if(a==null||!a.regionMatches(true,0,"Negotiate ",0,10))return null;byte[] token=Base64.getDecoder().decode(a.substring(10).trim());var x=(SpnegoAcceptor.Exchange)s.getAttribute("SPNEGO_EXCHANGE");if(x==null){x=spnego.begin();s.setAttribute("SPNEGO_EXCHANGE",x);}var r=x.accept(token);if(!r.established())return null;x.close();s.removeAttribute("SPNEGO_EXCHANGE");return ldap.resolve(new AdAuthenticationEvidence("microsoft-ad",r.principal(),"openidentity-ad-link-service",ExternalAdBindingV1.KERBEROS_SPNEGO,true,Map.of("gssEstablished",true)));}
 private static ResponseEntity<Map<String,Object>> challenge(byte[] x){HttpHeaders h=new HttpHeaders();h.set(HttpHeaders.WWW_AUTHENTICATE,"Negotiate");return new ResponseEntity<>(Map.of("status","NEGOTIATE_REQUIRED"),h,HttpStatus.UNAUTHORIZED);}
 private static byte[] dir(){return HexFormat.of().parseHex(env("OPENIDENTITY_AD_DIRECTORY_ID","d0d1d2d3d4d5d6d7d8d9dadbdcdddedf"));}private static byte[] random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return b;}private static long now(){return System.currentTimeMillis()/1000;}private static String hex(byte[] b){return HexFormat.of().formatHex(b);}private static String req(String n){String v=System.getenv(n);if(v==null||v.isBlank())throw new IllegalStateException("missing "+n);return v;}private static String env(String n,String d){String v=System.getenv(n);return v==null||v.isBlank()?d:v;}
}